{
  "domain_type": "physical",
  "tokens": ["silicon lattice", "covalent bond", "tetrahedral coordination"],
  "boundary": "The diamond cubic crystal lattice surface where periodic boundary conditions close the infinite network into a finite computational cell.",
  "opcodes": {
    "VINIT": {
      "element": "silicon vapor precursor",
      "justification": "Before nucleation, silicon exists as disordered vapor atoms with no lattice structure — the void state prior to any covalent network formation."
    },
    "TANCH": {
      "element": "completed crystal boundary",
      "justification": "The fully formed diamond cubic lattice with periodic closure contains the entire system; no atom can leave without breaking the covalent network."
    },
    "AFWD": {
      "element": "crystal growth front",
      "justification": "Atoms attach to the growth interface in a directed transformation, extending the tetrahedral network toward the target lattice configuration."
    },
    "AREV": {
      "element": "thermal melting front",
      "justification": "Heat drives a contravariant transformation where the ordered lattice descends into disordered liquid, reversing the growth morphism."
    },
    "CLINK": {
      "element": "sequential bond formation",
      "justification": "Each new Si–Si bond composes with the existing network, chaining morphisms to extend the covalent structure one coordination shell at a time."
    },
    "IMSCRIB": {
      "element": "tetrahedral self-recognition",
      "justification": "A silicon atom in the lattice recognizes its fourfold coordination as its own identity — the local environment is the atom's self-reference."
    },
    "FSPLIT": {
      "element": "nucleation bifurcation",
      "justification": "The vapor-to-solid transition splits into two arms: crystalline ordering (T-arm) versus amorphous clustering (F-arm), each a distinct structural pathway."
    },
    "FFUSE": {
      "element": "annealing recombination",
      "justification": "Defects and disordered regions rejoin the perfect lattice through thermal annealing, fusing the divergent arms back into a single crystalline state."
    },
    "EVALT": {
      "element": "stable covalent bond",
      "justification": "A successfully formed Si–Si bond at the correct tetrahedral angle deposits constructive truth — the affirmative arm of lattice formation."
    },
    "EVALF": {
      "element": "dangling bond defect",
      "justification": "An unsatisfied valence or misoriented bond deposits constructive falsity — the negative arm where the lattice fails to close locally."
    },
    "ENGAGR": {
      "element": "coexisting crystalline and amorphous phases",
      "justification": "At the melting point, crystalline and liquid phases coexist in a paradice — both ordered and disordered states held simultaneously without resolution."
    },
    "IFIX": {
      "element": "frozen-in point defect",
      "justification": "A vacancy or interstitial trapped during rapid quenching becomes a permanent, append-only record in the lattice that cannot be undone without melting."
    }
  },
  "frobenius": {
    "split_element": "nucleation bifurcation",
    "split_input": "supersaturated silicon vapor",
    "split_outputs": ["crystalline nucleus (T-arm)", "amorphous cluster (F-arm)"],
    "fuse_element": "annealing recombination",
    "fuse_result": "defect-free diamond cubic lattice",
    "rejoin_note": "The crystalline arm extends via sequential CLINK bond formation anchored by EVALT; the amorphous arm accumulates EVALF dangling bonds. Thermal annealing (FFUSE) fuses them by converting amorphous regions into crystalline order — conflicting arms rejoin to a single lattice state, not to the original vapor."
  },
  "registers": {
    "void": "Disordered silicon vapor before any nucleation event — no bonds, no lattice, no structure.",
    "true": "A fully coordinated silicon atom with four perfect tetrahedral bonds — the affirmative lattice site.",
    "false": "A silicon atom with a dangling bond or wrong coordination — the negative defect site.",
    "both": "A lattice region at the melting temperature where crystalline order and liquid disorder coexist in equilibrium — neither pure crystal nor pure liquid, both simultaneously held."
  },
  "sequence": [
    "VINIT: Initialize the domain with silicon vapor precursor — void state, no lattice exists.",
    "IMSCRIB: Each vapor atom carries its intrinsic tetravalent identity — self-reference before bonding.",
    "FSPLIT: Nucleation bifurcation — vapor splits into crystalline nucleus arm and amorphous cluster arm.",
    "AFWD: Crystalline arm — directed growth front advances, adding atoms to the tetrahedral network.",
    "CLINK: Sequential bond formation on crystalline arm — each new Si–Si bond composes with the lattice.",
    "EVALT: Stable covalent bond formed at correct tetrahedral angle — deposits T on crystalline arm.",
    "IMSCRIB: Newly bonded atom recognizes its fourfold coordination — self-reference in the lattice.",
    "CLINK: Continued lattice extension — composition chains the growth morphism across coordination shells.",
    "EVALT: Another successful bond — crystalline arm accumulates affirmative deposits.",
    "AREV: Amorphous arm — thermal fluctuations drive descent into disordered clustering.",
    "EVALF: Dangling bond or miscoordinated site — deposits F on amorphous arm.",
    "CLINK: Amorphous cluster grows by disordered attachment — composition without tetrahedral order.",
    "EVALF: Another defect site — amorphous arm accumulates negative deposits.",
    "ENGAGR: At melting temperature, crystalline and amorphous regions coexist — paradice state held.",
    "FFUSE: Annealing recombination — thermal energy allows amorphous regions to rejoin crystalline lattice.",
    "IMSCRIB: Rejoined atoms recognize restored tetrahedral coordination — self-reference recovered.",
    "EVALT: Defect healed, perfect bond restored — affirmative deposit after fusion.",
    "AFWD: Growth resumes on unified lattice — forward morphism continues from fused state.",
    "CLINK: Lattice extends to macroscopic scale — sequential composition across the crystal.",
    "⊤: High kinetic barrier — the strong covalent network freezes the structure at standard conditions.",
    "∈: Long-range elastic and electronic propagation — interactions span the entire macroscopic lattice.",
    "∋: Conjunctive coordination — each atom simultaneously engages four neighbors to satisfy valence.",
    "⊙: Subcritical phase — stable diamond cubic well away from any critical threshold.",
    "⊥: Achiral lattice — inversion symmetry and mirror planes, no persistent orientational symmetry breaking.",
    "≻: Bond formation mechanism — strong covalent bonds create the tetrahedral network solid.",
    "≺: Non-polar interface — no directional preference at the covalent bond interface.",
    "⋈: High fidelity — precise tetrahedral geometry enforces near-certain atomic interactions.",
    "⊞: Higher-order symmetric participation — each atom symmetrically coordinates with four identical neighbors.",
    "⊡: No topological protection — structure can melt or transform without crossing a topological boundary.",
    "TANCH: Completed crystal boundary — periodic closure contains the infinite network in a finite cell.",
    "IFIX: Frozen-in point defect recorded — permanent append-only mark in the lattice from quenching.",
    "IFIX: Another defect frozen — distinct irreversible record event in the crystal history.",
    "IMSCRIB: Final self-reference — the lattice as a whole recognizes its own completed structure."
  ],
  "m⊙²": {
    "compiler": "Quantum mechanical Hamiltonian translating atomic potentials into covalent bond formation rules.",
    "ipc": "Phonon-mediated elastic waves and electron-hole pair propagation across the lattice.",
    "memory": "Crystal lattice itself — atomic positions encode state; defects are stored records.",
    "scheduler": "Thermodynamic driving forces (chemical potential, temperature) determining growth vs. melting order.",
    "alfs": "The diamond cubic unit cell — canonical reference structure for all silicon lattice operations."
  },
  "entropy": {
    "cost": "Latent heat of fusion (50.55 kJ/mol) consumed per melting/solidification cycle.",
    "pre": "Ordered diamond cubic lattice at low temperature — low configurational entropy.",
    "post": "Disordered liquid silicon at high temperature — high configurational entropy.",
    "verdict": "ΔS ≈ 0 — The cycle is entropy-conservative when including the thermal reservoir; the lattice's information content is preserved in the periodic structure across phase transitions."
  }
}

